import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2016Q4 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2016Q4 Ceph社区季度进展报告","date":"2016-12-01T00:00:00.000Z","updated":"2016-12-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016Q4_Ceph社区季度总结.md","filePath":"posts/2016/2016Q4_Ceph社区季度总结.md","lastUpdated":1780460162000}'),t={name:"posts/2016/2016Q4_Ceph社区季度总结.md"};function i(n,o,s,h,p,_){return l(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="ceph-社区-2016q4-季度进展报告" tabindex="-1">Ceph 社区 2016Q4 季度进展报告 <a class="header-anchor" href="#ceph-社区-2016q4-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2016Q4 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 开发者月度会议围绕以下核心技术方向展开深入讨论：</p><ul><li><strong>内存管理优化</strong>：内存池分配器（Memory Pool Allocator）是本季度最突出的议题，重点解决 OSD 进程的内存碎片化问题</li><li><strong>服务质量（QoS）</strong>：基于 DM Block 算法的 QoS 实现，聚焦于区分背景 I/O 与客户端 I/O</li><li><strong>BlueStore 持续推进</strong>：会议明确将 BlueStore 开发进展列为持续关注项</li><li><strong>RBD 设备接口扩展</strong>：为 RBD 添加设备唯一 ID 查询能力</li></ul><p>详见 <a href="./2016-OCT-05_-_Ceph_Developer_Monthly.html">2016-OCT-05_-_-_Ceph_Developer_Monthly</a>。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="内存池分配器-memory-pool-allocator" tabindex="-1">内存池分配器（Memory Pool Allocator） <a class="header-anchor" href="#内存池分配器-memory-pool-allocator" aria-label="Permalink to &quot;内存池分配器（Memory Pool Allocator）&quot;">​</a></h3><p>Sage 主导设计了新的内存池分配器，核心特性包括：</p><ul><li>通过<strong>宏定义</strong>实现对象在正确内存池中的自动分配</li><li>支持编译时开启<strong>调试模式</strong>，可追踪对象分配情况</li><li>目标是解决 OSD 内存碎片化，并通过统计内存分配实现<strong>内存压力管理</strong></li><li>已完成部分类型的迁移，待性能分析验证无额外开销</li></ul><h3 id="boost-pool-与-slop-containers" tabindex="-1">Boost Pool 与 Slop Containers <a class="header-anchor" href="#boost-pool-与-slop-containers" aria-label="Permalink to &quot;Boost Pool 与 Slop Containers&quot;">​</a></h3><p>与内存池分配器采用相同底层技术，本季度已基本具备合并条件。合并后的重点工作是确定在代码库中的最优使用场景。</p><h3 id="rbd-设备查询接口" tabindex="-1">RBD 设备查询接口 <a class="header-anchor" href="#rbd-设备查询接口" aria-label="Permalink to &quot;RBD 设备查询接口&quot;">​</a></h3><p>Nitin 推进了 RBD 设备唯一 ID 查询接口的设计，涉及改动范围包括：</p><ul><li><code>libceph</code> 库层</li><li>RBD 类方法层</li><li>OSD 层</li></ul><p>该接口为上层应用提供设备标识能力，是 RBD 功能完善的重要一步。</p><h3 id="qos-—-dm-block-算法" tabindex="-1">QoS — DM Block 算法 <a class="header-anchor" href="#qos-—-dm-block-算法" aria-label="Permalink to &quot;QoS — DM Block 算法&quot;">​</a></h3><p>Josh 与 Erika 合作推进基于 <strong>DM Block 算法</strong>的 QoS 实现：</p><ul><li>核心目标：为不同客户端提供差异化服务质量保证</li><li>当前阶段重点：区分<strong>背景 I/O</strong>（如 recovery、scrub）与<strong>客户端 I/O</strong></li><li>Erika 负责性能测试，结果待分享</li></ul><p>详见 <a href="./2016-OCT-05_-_Ceph_Developer_Monthly.html">2016-OCT-05_-_-_Ceph_Developer_Monthly</a>。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p>| 决策事项 | 负责人 | 状态 | |---|---| | 内存池分配器性能分析 | Sage | 进行中 | | Boost Pool / Slop Containers 合并 | Sage 及相关开发者 | 待合并 | | RBD 设备查询接口开发 | Nitin | 进行中 | | QoS 算法开发与性能测试 | Josh / Erika | 进行中 |</p><ul><li><strong>BlueStore</strong> 被明确列为持续跟踪的战略性开发方向</li><li>确立了<strong>蓝图（Blueprint）讨论提前在 Wiki 上进行</strong>的社区协作规范，以提升会议效率</li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><ul><li><strong>Ceph Developer Monthly</strong> 会议正常举行，参与者包括 Sage Weil、Adam、Erika、Nitin、Josh 等核心开发者</li><li>社区鼓励开发者在会议前于 <strong>Wiki 上提前发起蓝图讨论</strong>，形成更结构化的议题准备流程</li><li>下次开发者月度会议计划于 <strong>2023年11月2日</strong>（原文所记录时间）东部时间晚上 9 点举行，重点议题为蓝图讨论</li></ul><blockquote><p>注：本季度仅有一篇会议记录材料，社区活动信息相对有限。</p></blockquote><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计后续工作重点方向如下：</p><ol><li><strong>内存池分配器落地</strong>：完成性能基准测试，推广到更多核心数据结构，正式合并 Boost Pool / Slop Containers</li><li><strong>QoS 性能数据公开</strong>：Erika 的测试结果将指导 DM Block 算法的调优方向，预计进入更广泛的评审阶段</li><li><strong>BlueStore 成熟度提升</strong>：作为持续关注项，预计在后续季度进入更多稳定性和性能验证工作</li><li><strong>RBD 接口完善</strong>：设备查询接口涉及多层改动，预计在下季度完成跨层联调并提交 PR</li><li><strong>蓝图驱动开发</strong>：社区推动提前在 Wiki 讨论蓝图的机制，预计后续季度的月度会议议题质量将进一步提升</li></ol><hr><p><em>本报告基于 <a href="/VideoSummary/posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.html">2016-OCT-05_-_-_Ceph_Developer_Monthly</a>) 一篇材料生成。本季度可用材料较少，部分章节信息密度有限，建议结合同期邮件列表和 GitHub PR 记录补充。</em></p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.html">2016-OCT-05 :: Ceph Developer Monthly</a>)</li></ul>',38)])])}const u=e(t,[["render",i]]);export{d as __pageData,u as default};
